export const countSummary = (total: string, from: string, to: string, lang: Lang): string => {
    switch (lang) {
        case "en":
            return `${from}–${to} of ${total} results`;
        case "ja":
            return `全${total}件中 ${from}–${to}件`;
        case "zh":
            return `共${total}条中的第${from}–${to}条`;
        default:
            return `총 ${total}건 중 ${from}–${to}건`;
    }
};

